type Section = "Overview" | "Data connectors" | "Decision profiles" | "Risk assessments";
type Level = "Critical" | "High" | "Medium" | "Low";
type DecisionOutput = { status:"success"|"failed"; profileName?:string; provider?:string; model?:string; fallbackUsed?:boolean; riskDetected?:boolean; riskProbability?:number; riskType?:string; severity?:Level; confidence?:number; policy?:string; humanApprovalRequired?:boolean; rationale?:string; recommendedActions?:string[]; error?:string; providerErrors?:string[] };
type Risk = { id: string; title: string; team: string; level: Level; status: "Needs review" | "Monitoring" | "Resolved"; detail: string; source: string; time: string; owner: string; evidence: string; recommendation: string; decision?: DecisionOutput | null };
type Connector = { name: string; team: string; description: string; status: "Connected" | "Not connected" | "Needs attention" | "Demo data"; lastSync: string };
type Profile = { id: string; name: string; team: string; description: string; active: boolean; predicate: string; choices: string; scores: string; fields: string; approval: string; sources?: string };

