const nav: {label:Section;icon:any}[] = [{label:"Overview",icon:LayoutDashboard},{label:"Data connectors",icon:Link2},{label:"Decision profiles",icon:SlidersHorizontal},{label:"Risk assessments",icon:ShieldAlert}];
const teams = ["Engineering","Finance","HR","Operations","Cross-team"];
const levels: Level[] = ["Low","Medium","High","Critical"];
const cls = (...s:string[]) => s.filter(Boolean).join(" ");
function sourceNames(profile:Profile){return [...new Set(String(profile.sources||"").split(",").map(value=>value.trim()).filter(Boolean))];}
function decisionOutput(data:any,profile?:Profile):DecisionOutput{return {status:"success",profileName:data.profileUsed?.name||profile?.name||"Default decision profile",provider:data.provider,model:data.model,riskDetected:data.assessment.riskDetected,riskProbability:data.assessment.riskProbability,riskType:data.assessment.riskType,severity:data.assessment.severity,confidence:data.assessment.confidence,policy:data.assessment.policy,humanApprovalRequired:data.assessment.humanApprovalRequired,rationale:data.assessment.rationale,recommendedActions:Array.isArray(data.assessment.recommendedActions)?data.assessment.recommendedActions:[]};}
function normalizeDecisionOutput(decision?:DecisionOutput|null):DecisionOutput|null|undefined{if(!decision||decision.status!=="success")return decision;const likelihood=typeof decision.riskProbability==="number"?`${Math.round(decision.riskProbability*100)}% probability of material risk`:"Probability was not returned";return{...decision,rationale:[`Risk likelihood: ${likelihood}`,`Classification: ${decision.riskType||"No category was returned"}`,`Severity: ${decision.severity||"No severity was returned"}`,`Review requirement: ${decision.humanApprovalRequired?"Human review is required before action":"Eligible for the configured automated policy"}`].join("\n")};}
function severity(level:Level){return level==="Critical"?"bg-red-100 text-red-700":level==="High"?"bg-orange-100 text-orange-700":level==="Medium"?"bg-amber-100 text-amber-800":"bg-emerald-100 text-emerald-700";}
function Button({children,onClick,secondary=false,disabled=false}:{children:React.ReactNode;onClick?:()=>void;secondary?:boolean;disabled?:boolean}){return <button disabled={disabled} onClick={onClick} className={cls("inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold transition disabled:cursor-not-allowed disabled:opacity-50",secondary?"border border-slate-200 bg-white text-slate-700 hover:bg-slate-50":"bg-[#176B57] text-white hover:bg-[#115642]")}>{children}</button>}
function Pill({children}:{children:React.ReactNode}){return <span className="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-semibold text-slate-600">{children}</span>}
function TeamIcon({team}:{team:string}){const I=team==="Engineering"?GitBranch:team==="Finance"?DollarSign:team==="HR"?Users:team==="Operations"?Boxes:BriefcaseBusiness;return <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-emerald-50 text-emerald-800"><I size={17}/></span>}
function Field({label,value,onChange,placeholder}:{label:string;value:string;onChange:(v:string)=>void;placeholder?:string}){return <label className="block"><span className="mb-1.5 block text-xs font-bold text-slate-600">{label}</span><input value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder} className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm outline-none focus:border-emerald-700 focus:ring-2 focus:ring-emerald-100"/></label>}
function connectorSetup(name:string){
 const normalized=name.toLowerCase();
 if(normalized==="github")return {variables:["GITHUB_TOKEN","GITHUB_REPO"],steps:["Create a fine-grained GitHub token with read access to pull requests and repository metadata.","Set GITHUB_REPO to owner/repository and add both variables to .env.local or Vercel.","Restart or redeploy Sentinel, then select Sync configured sources."]};
 if(normalized==="jira")return {variables:["JIRA_BASE_URL","JIRA_EMAIL","JIRA_API_TOKEN","JIRA_JQL (optional)"],steps:["Create a Jira API token for a read-only integration account.","Add the Jira site URL, account email, token, and optional JQL to .env.local or Vercel.","Restart or redeploy Sentinel, then select Sync configured sources."]};
 if(normalized==="google drive")return {variables:["GOOGLE_SERVICE_ACCOUNT_JSON","GOOGLE_DRIVE_FOLDER_ID"],steps:["Enable the Google Drive API and create a service account.","Share the source folder with the service account email as a viewer.","Add the one-line service account JSON and folder ID to .env.local or Vercel, then sync."]};
 return {variables:["SENTINEL_INGEST_TOKEN"],steps:["Create a long random ingestion token and add it to .env.local or Vercel.","Send normalized events to POST /api/ingest with Authorization: Bearer <token>.","For a custom live sync, add a server-side connector adapter before storing provider credentials."]};
}
type ConnectorConfig = Record<string,string>;
type ConnectionResult = { ok:boolean; message:string };
function ConnectorCredentialsForm({name,onConnect}:{name:string;onConnect:(config:ConnectorConfig)=>Promise<ConnectionResult>}){
 const isGitHub=name==="GitHub";
 const [repository,setRepository]=useState("");
 const [baseUrl,setBaseUrl]=useState("");
 const [email,setEmail]=useState("");
 const [token,setToken]=useState("");
 const [jql,setJql]=useState("statusCategory != Done ORDER BY priority DESC, updated ASC");
 const [connecting,setConnecting]=useState(false);
 const [result,setResult]=useState<ConnectionResult|null>(null);
 async function submit(event:React.FormEvent){event.preventDefault();setResult(null);if(isGitHub&&(!repository.trim()||!token.trim())){setResult({ok:false,message:"Enter both the repository URL and access token."});return;}if(!isGitHub&&(!baseUrl.trim()||!email.trim()||!token.trim())){setResult({ok:false,message:"Enter the Jira URL, email, and API token."});return;}setConnecting(true);try{const response=await onConnect(isGitHub?{repository,token}:{baseUrl,email,token,jql});setResult(response);if(response.ok)setToken("");}finally{setConnecting(false);}}
 return <form onSubmit={submit} className="mt-4 rounded-xl border border-emerald-200 bg-emerald-50/60 p-4"><div className="flex items-start gap-2"><Link2 size={16} className="mt-0.5 shrink-0 text-emerald-800"/><div><p className="text-xs font-bold text-emerald-950">Connect {name}</p><p className="mt-1 text-[11px] leading-5 text-slate-600">Credentials are sent to this server for one connection request and are not stored in Neon or browser storage.</p></div></div><div className="mt-4 space-y-3">{isGitHub?<><label className="block"><span className="mb-1.5 block text-xs font-bold text-slate-600">Repository URL</span><input type="url" required value={repository} onChange={event=>setRepository(event.target.value)} placeholder="https://github.com/owner/repository" autoComplete="off" spellCheck={false} className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm outline-none focus:border-emerald-700 focus:ring-2 focus:ring-emerald-100"/></label><label className="block"><span className="mb-1.5 block text-xs font-bold text-slate-600">Fine-grained access token</span><input type="password" required value={token} onChange={event=>setToken(event.target.value)} placeholder="Read-only repository token" autoComplete="new-password" spellCheck={false} className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm outline-none focus:border-emerald-700 focus:ring-2 focus:ring-emerald-100"/></label></>:<><label className="block"><span className="mb-1.5 block text-xs font-bold text-slate-600">Jira Cloud URL</span><input type="url" required value={baseUrl} onChange={event=>setBaseUrl(event.target.value)} placeholder="https://your-company.atlassian.net" autoComplete="url" spellCheck={false} className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm outline-none focus:border-emerald-700 focus:ring-2 focus:ring-emerald-100"/></label><div className="grid gap-3 sm:grid-cols-2"><label className="block"><span className="mb-1.5 block text-xs font-bold text-slate-600">Jira account email</span><input type="email" required value={email} onChange={event=>setEmail(event.target.value)} placeholder="integration@company.com" autoComplete="email" className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm outline-none focus:border-emerald-700 focus:ring-2 focus:ring-emerald-100"/></label><label className="block"><span className="mb-1.5 block text-xs font-bold text-slate-600">Jira API token</span><input type="password" required value={token} onChange={event=>setToken(event.target.value)} placeholder="API token" autoComplete="new-password" spellCheck={false} className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm outline-none focus:border-emerald-700 focus:ring-2 focus:ring-emerald-100"/></label></div><label className="block"><span className="mb-1.5 block text-xs font-bold text-slate-600">JQL filter</span><input value={jql} onChange={event=>setJql(event.target.value)} spellCheck={false} className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 font-mono text-xs outline-none focus:border-emerald-700 focus:ring-2 focus:ring-emerald-100"/></label></>}</div>{result&&<p role="status" className={cls("mt-3 rounded-lg px-3 py-2 text-xs leading-5",result.ok?"bg-white text-emerald-800":"bg-red-50 text-red-700")}>{result.message}</p>}<button type="submit" disabled={connecting} className="mt-4 inline-flex min-h-10 items-center justify-center gap-2 rounded-xl bg-[#176B57] px-4 py-2.5 text-sm font-semibold text-white transition-[background-color,transform] duration-150 hover:bg-[#115642] active:scale-[0.96] disabled:cursor-wait disabled:opacity-60"><Link2 size={16}/>{connecting?"Connecting…":`Connect ${name}`}</button></form>;
}
function ConnectorCard({connector,onRemove,onConnect}:{connector:Connector;onRemove:()=>void;onConnect:(config:ConnectorConfig)=>Promise<ConnectionResult>}){
 const [showSetup,setShowSetup]=useState(false);
 const setup=connectorSetup(connector.name);
 const panelId=`connector-${connector.name.toLowerCase().replace(/[^a-z0-9]+/g,"-")}-setup`;
 return <div className="flex flex-col rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-start justify-between"><TeamIcon team={connector.team}/><Pill>{connector.status}</Pill></div><h3 className="mt-4 font-bold">{connector.name}</h3><p className="mt-1 min-h-10 text-xs leading-5 text-slate-500">{connector.description}</p><p className="mt-4 text-[11px] text-slate-400">{connector.team} · {connector.lastSync}</p><div className="mt-4 flex gap-2 border-t border-slate-100 pt-4"><button type="button" aria-expanded={showSetup} aria-controls={panelId} onClick={()=>setShowSetup(open=>!open)} className="inline-flex min-h-10 items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-semibold text-slate-700 transition-[color,background-color,border-color,transform] duration-150 hover:bg-slate-50 active:scale-[0.96]"><CircleHelp size={16}/>{showSetup?"Hide connection":"Connect / setup"}<ChevronDown size={15} className={cls("transition-transform duration-150",showSetup?"rotate-180":"rotate-0")}/></button><button title="Remove connector" onClick={onRemove} className="ml-auto min-h-10 rounded-lg px-3 text-slate-400 transition-[color,background-color,transform] duration-150 hover:bg-red-50 hover:text-red-600 active:scale-[0.96]"><Trash2 size={16}/></button></div>{showSetup&&<div id={panelId} className="mt-4 rounded-xl bg-slate-50 p-4">{(connector.name==="GitHub"||connector.name==="Jira")&&<ConnectorCredentialsForm name={connector.name} onConnect={onConnect}/>}<div className={(connector.name==="GitHub"||connector.name==="Jira")?"mt-4 border-t border-slate-200 pt-4":""}><p className="text-[10px] font-bold uppercase tracking-[.14em] text-slate-400">Server environment alternative</p><div className="mt-2 flex flex-wrap gap-1.5">{setup.variables.map(variable=><code key={variable} className="rounded-md border border-slate-200 bg-white px-2 py-1 text-[10px] text-slate-600">{variable}</code>)}</div><ol className="mt-3 space-y-2 text-xs leading-5 text-slate-600">{setup.steps.map((step,index)=><li key={step} className="flex gap-2"><span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-emerald-100 text-[10px] font-bold text-emerald-800">{index+1}</span><span>{step}</span></li>)}</ol><p className="mt-3 border-t border-slate-200 pt-3 text-[11px] leading-5 text-slate-500">For persistent production connections, keep credentials server-side in Vercel. See CONNECTORS.md for permission guidance.</p></div></div>}</div>;
}
type QuickProfile = Pick<Profile,"predicate"|"choices"|"scores">;
type TestData = { title:string; team:string; profileId:string; question:string; fileName:string; fileText:string; quickProfile?:QuickProfile };
const SAMPLE_QUESTION="Based on the uploaded release signals, is the release at risk? Choose the most likely risk type, assign a severity, explain the evidence, and state whether human approval is required.";
const SAMPLE_FILE=JSON.stringify({source:"release-readiness-test",release:{name:"Customer portal Q4 release",date:"2026-11-15",daysRemaining:14},signals:{criticalBugs:3,blockedPullRequests:2,oldestBlockedHours:61,testPassRatePercent:84,releaseOwnerAvailable:false},constraints:["Regulatory review must finish before launch","The customer contract deadline cannot move"],notes:"A backup release owner has not been assigned."},null,2);
const EXPENSE_SAMPLE_QUESTION="Should this expense claim be reimbursed automatically or held for human review? Choose the main issue, assign a severity, explain the evidence, and state the next action.";
const EXPENSE_SAMPLE_FILE=JSON.stringify({source:"expense-claim-test",claim:{employee:"Maya Rao",category:"Client meal",amount:185,currency:"USD",policyLimit:100,receiptAttached:true,managerApproved:false,duplicateDetected:false,submittedDaysAfterExpense:2},notes:"Six customers attended, but attendee names were not included."},null,2);
function QuickTestDataSource({profiles,onUse}:{profiles:Profile[];onUse:(data:TestData)=>void}){
 const availableProfiles=profiles.some(profile=>profile.id===expenseClaimProfile.id)?profiles:[...profiles,expenseClaimProfile];
 const defaultProfile=availableProfiles.find(profile=>profile.active)||availableProfiles[0];
 const [title,setTitle]=useState("");
 const [team,setTeam]=useState(defaultProfile?.team||"Engineering");
 const [profileId,setProfileId]=useState(defaultProfile?.id||"");
 const [question,setQuestion]=useState("");
 const [fileName,setFileName]=useState("");
 const [fileText,setFileText]=useState("");
 const [message,setMessage]=useState("");
 const [quickPredicate,setQuickPredicate]=useState("Is this situation a material risk?");
 const [quickChoices,setQuickChoices]=useState("Policy issue, Financial risk, Delivery risk, No material risk");
 const [quickScores,setQuickScores]=useState("Low, Medium, High, Critical");
 const selectedProfile=availableProfiles.find(profile=>profile.id===profileId);
 const quickProfileValid=Boolean(quickPredicate.trim()&&new Set(quickChoices.split(",").map(value=>value.trim()).filter(Boolean)).size>=2&&new Set(quickScores.split(",").map(value=>value.trim()).filter(Boolean)).size>=2);
 const canUse=Boolean(question.trim()||fileText.trim())&&Boolean(selectedProfile||quickProfileValid);
 async function selectFile(file?:File){
  setMessage("");
  if(!file){setFileName("");setFileText("");return;}
  if(file.size>100_000){setMessage("Choose a file smaller than 100 KB for a quick test.");return;}
  try{let text=await file.text();if(file.name.toLowerCase().endsWith(".json")){try{text=JSON.stringify(JSON.parse(text),null,2);}catch{setMessage("The JSON is not valid, so it was loaded as plain text.");}}if(text.length>50_000){text=text.slice(0,50_000);setMessage("Only the first 50,000 characters will be used.");}setFileName(file.name);setFileText(text);}catch{setMessage("Sentinel could not read that file.");}
 }
 function chooseTeam(nextTeam:string){setTeam(nextTeam);const match=availableProfiles.find(profile=>profile.team===nextTeam&&profile.active)||availableProfiles.find(profile=>profile.team===nextTeam);if(match)setProfileId(match.id);}
 function chooseProfile(nextId:string){setProfileId(nextId);const profile=availableProfiles.find(item=>item.id===nextId);if(profile)setTeam(profile.team);}
 function loadReleaseSample(){const profile=availableProfiles.find(item=>item.id==="release-readiness")||availableProfiles.find(item=>item.team==="Engineering"&&item.active)||availableProfiles[0];setTitle("Test release readiness risk");setQuestion(SAMPLE_QUESTION);setFileName("release-risk-test.json");setFileText(SAMPLE_FILE);setMessage("Release sample loaded. Review the selected profile, then use it as an assessment.");if(profile){setProfileId(profile.id);setTeam(profile.team);}}
 function loadExpenseSample(){setTitle("Test expense claim review");setQuestion(EXPENSE_SAMPLE_QUESTION);setFileName("expense-claim-test.json");setFileText(EXPENSE_SAMPLE_FILE);setMessage("Expense sample loaded. Review the selected profile, then use it as an assessment.");setProfileId(expenseClaimProfile.id);setTeam(expenseClaimProfile.team);}
 function clearFile(){setFileName("");setFileText("");setMessage("");}
 function submit(){if(!canUse){setMessage("Add a question or file. A quick profile also needs a Predicate, at least two Choices, and at least two Score levels.");return;}onUse({title,team,profileId,question,fileName,fileText,quickProfile:selectedProfile?undefined:{predicate:quickPredicate.trim(),choices:quickChoices.trim(),scores:quickScores.trim()}});}
 return <section className="mt-6 rounded-2xl border border-emerald-200 bg-white p-5 sm:p-6"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div className="flex gap-3"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-emerald-50 text-emerald-800"><FileText size={19}/></span><div><h2 className="font-bold">Quick test data</h2><p className="mt-1 max-w-2xl text-xs leading-5 text-slate-500">Choose the decision profile that defines the question, allowed risk types, severity scale, and expected fields. Then type a situation, attach a file, or load the sample.</p></div></div><Pill>Local preview</Pill></div><div className="mt-5 grid gap-3 lg:grid-cols-2"><div className="rounded-xl bg-emerald-50 p-4"><p className="text-xs font-bold text-emerald-900">Expense-claim example · Easiest</p><p className="mt-1 text-[11px] leading-5 text-slate-600">A $185 meal claim exceeds a $100 limit and has no manager approval.</p><div className="mt-4 flex flex-wrap gap-2"><a href="/samples/expense-claim-test.json" download className="inline-flex min-h-10 items-center justify-center gap-2 rounded-xl border border-emerald-200 bg-white px-3 py-2 text-xs font-semibold text-emerald-800 transition-[background-color,transform] duration-150 hover:bg-emerald-50 active:scale-[0.96]"><FileDown size={15}/>Download JSON</a><button type="button" onClick={loadExpenseSample} className="inline-flex min-h-10 items-center justify-center gap-2 rounded-xl bg-[#176B57] px-3 py-2 text-xs font-semibold text-white transition-[background-color,transform] duration-150 hover:bg-[#115642] active:scale-[0.96]"><Sparkles size={15}/>Load expense sample</button></div></div><div className="rounded-xl bg-slate-50 p-4"><p className="text-xs font-bold text-slate-700">Release-readiness example</p><p className="mt-1 text-[11px] leading-5 text-slate-600">Engineering signals for testing a release-risk decision.</p><div className="mt-4 flex flex-wrap gap-2"><a href="/samples/release-risk-test.json" download className="inline-flex min-h-10 items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-semibold text-slate-700 transition-[background-color,transform] duration-150 hover:bg-slate-50 active:scale-[0.96]"><FileDown size={15}/>Download JSON</a><button type="button" onClick={loadReleaseSample} className="inline-flex min-h-10 items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-semibold text-slate-700 transition-[background-color,transform] duration-150 hover:bg-slate-50 active:scale-[0.96]"><Sparkles size={15}/>Load release sample</button></div></div></div><div className="mt-5 grid gap-4 lg:grid-cols-2"><div className="space-y-4"><Field label="Assessment title (optional)" value={title} onChange={setTitle} placeholder="e.g. Test supplier delivery risk"/><div className="grid gap-4 sm:grid-cols-2"><label className="block"><span className="mb-1.5 block text-xs font-bold text-slate-600">Team</span><select value={team} onChange={event=>chooseTeam(event.target.value)} className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm outline-none focus:border-emerald-700 focus:ring-2 focus:ring-emerald-100">{teams.map(option=><option key={option}>{option}</option>)}</select></label><label className="block"><span className="mb-1.5 block text-xs font-bold text-slate-600">Decision profile</span><select value={profileId} onChange={event=>chooseProfile(event.target.value)} className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm outline-none focus:border-emerald-700 focus:ring-2 focus:ring-emerald-100"><option value="">Quick profile · Enter below</option>{availableProfiles.map(profile=><option key={profile.id} value={profile.id}>{profile.name}{profile.active?" · Active":" · Draft"}</option>)}</select></label></div>{selectedProfile&&<div className="rounded-xl border border-slate-200 bg-slate-50 p-3"><div className="flex items-center justify-between gap-2"><p className="text-xs font-bold text-slate-700">{selectedProfile.name}</p><Pill>{selectedProfile.active?"Active":"Draft test"}</Pill></div><dl className="mt-3 space-y-2 text-[11px] leading-5"><div><dt className="font-bold text-slate-500">Predicate</dt><dd className="text-slate-600">{selectedProfile.predicate}</dd></div><div><dt className="font-bold text-slate-500">Allowed choices</dt><dd className="text-slate-600">{selectedProfile.choices}</dd></div><div><dt className="font-bold text-slate-500">Output format</dt><dd className="break-words text-slate-600">{selectedProfile.fields}</dd></div></dl></div>}{!selectedProfile&&<div className="rounded-xl border border-emerald-200 bg-emerald-50/60 p-4"><div className="flex items-start gap-2"><SlidersHorizontal size={16} className="mt-0.5 shrink-0 text-emerald-800"/><div><p className="text-xs font-bold text-emerald-950">Quick profile</p><p className="mt-1 text-[11px] leading-5 text-slate-600">Use these temporary settings for this test. They will not be added to Decision profiles.</p></div></div><div className="mt-4 space-y-3"><Field label="Predicate question" value={quickPredicate} onChange={setQuickPredicate} placeholder="Is this situation a material risk?"/><Field label="Choices (comma-separated, at least 2)" value={quickChoices} onChange={setQuickChoices} placeholder="Delay, Quality issue, No material risk"/><Field label="Score levels (ordered, at least 2)" value={quickScores} onChange={setQuickScores} placeholder="Low, Medium, High, Critical"/></div>{!quickProfileValid&&<p className="mt-3 text-xs leading-5 text-amber-800">Complete all three fields and provide at least two unique Choices and Score levels.</p>}</div>}<label className="block"><span className="mb-1.5 block text-xs font-bold text-slate-600">Question or situation</span><textarea rows={5} maxLength={8000} value={question} onChange={event=>setQuestion(event.target.value)} placeholder="What risk should Sentinel assess? Include any constraints or expected outcome." className="w-full resize-y rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm outline-none focus:border-emerald-700 focus:ring-2 focus:ring-emerald-100"/><span className="mt-1 block text-right text-[10px] text-slate-400">{question.length}/8,000</span></label></div><div><p className="mb-1.5 text-xs font-bold text-slate-600">Supporting file</p><input id="quick-test-file" type="file" accept=".txt,.md,.csv,.json,text/plain,text/csv,application/json" className="sr-only" onChange={event=>selectFile(event.target.files?.[0])}/><label htmlFor="quick-test-file" className="flex min-h-32 cursor-pointer flex-col items-center justify-center rounded-xl border border-dashed border-slate-300 bg-slate-50 px-4 py-5 text-center transition-[color,background-color,border-color,transform] duration-150 hover:border-emerald-400 hover:bg-emerald-50/40 active:scale-[0.96]"><Upload size={20} className="text-emerald-800"/><span className="mt-2 text-sm font-semibold text-slate-700">Choose a test file</span><span className="mt-1 text-[11px] text-slate-400">TXT, Markdown, CSV, or JSON · 100 KB maximum</span></label>{fileName&&<div className="mt-3 rounded-xl border border-slate-200 p-3"><div className="flex items-center gap-2"><FileText size={15} className="text-emerald-800"/><span className="min-w-0 flex-1 truncate text-xs font-semibold">{fileName}</span><button type="button" onClick={clearFile} className="rounded-lg p-1.5 text-slate-400 transition-[color,background-color,transform] duration-150 hover:bg-red-50 hover:text-red-600 active:scale-[0.96]" aria-label="Remove selected file"><X size={14}/></button></div><pre className="mt-3 max-h-64 overflow-auto whitespace-pre-wrap rounded-lg bg-slate-50 p-3 text-[10px] leading-4 text-slate-500">{fileText.slice(0,3000)}{fileText.length>3000?"…":""}</pre></div>}{message&&<p className="mt-3 text-xs leading-5 text-amber-700" role="status">{message}</p>}</div></div><div className="mt-5 flex flex-col justify-between gap-3 border-t border-slate-100 pt-4 sm:flex-row sm:items-center"><p className="text-[11px] leading-5 text-slate-500">The selected profile is sent with the evidence when you save the assessment. Files stay in your browser until then.</p><button type="button" disabled={!canUse} onClick={submit} className="inline-flex min-h-10 shrink-0 items-center justify-center gap-2 rounded-xl bg-[#176B57] px-4 py-2.5 text-sm font-semibold text-white transition-[background-color,transform] duration-150 hover:bg-[#115642] active:scale-[0.96] disabled:cursor-not-allowed disabled:opacity-50"><ArrowRight size={16}/>Use as assessment</button></div></section>;
}
export default function Home(){
 const [hydrated, setHydrated] = useState(false);
 const [syncing, setSyncing] = useState(false);
 const [section,setSection]=useState<Section>("Overview");
 const [risks,setRisks]=useState<Risk[]>(seedRisks);
 const [connectors,setConnectors]=useState<Connector[]>(seedConnectors);
 const [profiles,setProfiles]=useState<Profile[]>(seedProfiles);
 const [search,setSearch]=useState("");
 const [toast,setToast]=useState("");
 const [modal,setModal]=useState<"assessment"|"connector"|"profile"|null>(null);
 const [selectedRisk,setSelectedRisk]=useState<Risk|null>(null);
 const [selectedProfile,setSelectedProfile]=useState<Profile|null>(null);
 const [riskLevel,setRiskLevel]=useState("All levels");
 const [riskStatus,setRiskStatus]=useState("All statuses");
 const [teamFilter,setTeamFilter]=useState("All teams");
 const [assessment,setAssessment]=useState({title:"",team:"Engineering",detail:"",level:"Medium" as Level,source:"Manual assessment",evidence:"",recommendation:""});
 const [assessmentFileName,setAssessmentFileName]=useState("");
 const [assessmentProfileId,setAssessmentProfileId]=useState("");
 const [assessmentQuickProfile,setAssessmentQuickProfile]=useState<QuickProfile|null>(null);
 const [connectorDraft,setConnectorDraft]=useState({name:"",team:"Engineering",description:""});
 const [profileDraft,setProfileDraft]=useState<Profile>(seedProfiles[0]);
 const [mobileNav,setMobileNav]=useState(false);
 useEffect(()=>{
  if(!modal&&!selectedRisk&&!mobileNav)return;
  const previousOverflow=document.body.style.overflow;
  const previousPaddingRight=document.body.style.paddingRight;
  const scrollbarWidth=window.innerWidth-document.documentElement.clientWidth;
  document.body.style.overflow="hidden";
  if(scrollbarWidth>0)document.body.style.paddingRight=`${scrollbarWidth}px`;
  return()=>{document.body.style.overflow=previousOverflow;document.body.style.paddingRight=previousPaddingRight;};
 },[modal,selectedRisk,mobileNav]);
 useEffect(()=>{let cancelled=false;(async()=>{try{const res=await fetch("/api/data",{cache:"no-store"});if(!res.ok)throw new Error("Neon data unavailable");const payload=await res.json();if(cancelled)return;if(payload.state){const s=payload.state;if(Array.isArray(s.risks))setRisks(s.risks.map((risk:Risk)=>({...risk,decision:normalizeDecisionOutput(risk.decision)})));if(Array.isArray(s.connectors))setConnectors(s.connectors);if(Array.isArray(s.profiles))setProfiles(s.profiles.some((profile:Profile)=>profile.id===expenseClaimProfile.id)?s.profiles:[...s.profiles,expenseClaimProfile]);}else{await fetch("/api/data",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({risks:seedRisks,connectors:seedConnectors,profiles:seedProfiles})});}setHydrated(true);}catch{if(!cancelled){setHydrated(true);notify("Database unavailable. Check DATABASE_URL before relying on saved data.");}}})();return()=>{cancelled=true;}},[]);
 useEffect(()=>{if(!hydrated)return;const timer=window.setTimeout(()=>{fetch("/api/data",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({risks,connectors,profiles})}).then(r=>{if(!r.ok)notify("Could not save to Neon. Check database configuration.");}).catch(()=>notify("Could not reach Neon database."));},450);return()=>window.clearTimeout(timer);},[risks,connectors,profiles,hydrated]);
 function notify(s:string){setToast(s);window.setTimeout(()=>setToast(""),2600);}
 function useTestData(data:TestData){const question=data.question.trim();const fileEvidence=data.fileText.trim();if(data.profileId===expenseClaimProfile.id)setProfiles(old=>old.some(profile=>profile.id===expenseClaimProfile.id)?old:[...old,expenseClaimProfile]);setAssessmentProfileId(data.profileId);setAssessmentQuickProfile(data.quickProfile||null);setAssessment({title:data.title.trim()||`Test: ${data.fileName||question.slice(0,60)||"Risk question"}`,team:data.team,detail:question||`Assess the uploaded file ${data.fileName} for material organizational risk.`,level:"Medium",source:data.fileName?`Uploaded test file · ${data.fileName}`:"Typed test question",evidence:fileEvidence?`Uploaded file: ${data.fileName}\n\n${fileEvidence}`:`User-supplied test question: ${question}`,recommendation:""});setModal("assessment");}
 const shownRisks=useMemo(()=>risks.filter(r=>(`${r.title} ${r.team} ${r.detail} ${r.id}`.toLowerCase().includes(search.toLowerCase()))&&(riskLevel==="All levels"||r.level===riskLevel)&&(riskStatus==="All statuses"||r.status===riskStatus)),[risks,search,riskLevel,riskStatus]);
 const shownConnectors=connectors.filter(c=>(teamFilter==="All teams"||c.team===teamFilter)&&`${c.name} ${c.team} ${c.description}`.toLowerCase().includes(search.toLowerCase()));
 function chooseAssessmentProfile(id:string){setAssessmentQuickProfile(null);setAssessmentProfileId(id);const profile=profiles.find(item=>item.id===id);if(profile)setAssessment(current=>({...current,team:profile.team}));}
 function chooseAssessmentSource(name:string){
  if(name==="Manual assessment"||name==="File upload"){setAssessmentFileName("");setAssessment(current=>({...current,source:name}));return;}
  setAssessmentFileName("");
  const connector=connectors.find(item=>item.name===name);
  const latest=risks.find(risk=>risk.source===name||risk.source.startsWith(`${name} ·`));
  const mappedProfile=profiles.find(profile=>profile.active&&sourceNames(profile).includes(name))||profiles.find(profile=>profile.active&&profile.team===connector?.team);
  setAssessment(current=>({...current,source:name,team:mappedProfile?.team||connector?.team||current.team,title:current.title||latest?.title||"",detail:latest?.detail||current.detail,evidence:latest?.evidence||current.evidence}));
  setAssessmentQuickProfile(null);setAssessmentProfileId(mappedProfile?.id||"");
  notify(latest?`${name} evidence loaded from the latest synchronized risk.`:`No synchronized ${name} evidence is available yet. Sync the connector first or paste evidence manually.`);
 }
 async function uploadAssessmentFile(file?:File){
  if(!file)return;
  if(file.size>100*1024){notify("Choose a text file smaller than 100 KB.");return;}
  const extension=file.name.split(".").pop()?.toLowerCase();
  if(!extension||!["txt","md","csv","json"].includes(extension)){notify("Use a TXT, Markdown, CSV, or JSON file.");return;}
  try{
   const content=await file.text();
   setAssessmentFileName(file.name);
   setAssessment(current=>({...current,source:"File upload",title:current.title||`Review ${file.name}`,detail:current.detail||`Assess the uploaded file ${file.name} for material risk.`,evidence:`Uploaded file: ${file.name}\n\n${content}`}));
   notify(`${file.name} added as supporting evidence.`);
  }catch{notify("This file could not be read. Choose another text file.");}
 }
 async function createAssessment(){
  if(!assessment.title.trim()||!assessment.detail.trim()){notify("Add a title and situation before creating the assessment.");return;}
  const profile=assessmentQuickProfile?{id:"quick-test-inline",name:"Quick test profile",team:assessment.team,description:"Temporary profile entered in Quick test data.",active:true,fields:"risk_detected, risk_type, severity, evidence, recommendation, confidence, human_approval_required",approval:"High or Critical severity; low confidence; missing evidence",...assessmentQuickProfile}:profiles.find(p=>p.id===assessmentProfileId)||profiles.find(p=>p.active&&p.team===assessment.team)||profiles.find(p=>p.active);
  let level:Level=assessment.level;
  let recommendation=assessment.recommendation.trim();
  let decision:DecisionOutput|null=null;
  let modelNote="OpenAI Decisions was not completed; manual severity retained.";
  try{
   const source=assessment.source==="File upload"&&assessmentFileName?`Uploaded file · ${assessmentFileName}`:assessment.source;
   const response=await fetch("/api/decisions",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({state:{title:assessment.title,team:assessment.team,detail:assessment.detail,evidence:assessment.evidence,source},profile:profile?{id:profile.id,name:profile.name,predicate:profile.predicate,choices:profile.choices,scores:profile.scores,fields:profile.fields,approval:profile.approval}:undefined})});
   const data=await response.json();
   if(response.ok&&data.assessment){
    level=data.assessment.severity as Level;
    decision=decisionOutput(data,profile);
    modelNote=`Luna completed the ${decision.profileName} profile.`;
    if(!recommendation)recommendation=decision.recommendedActions?.[0]||(decision.humanApprovalRequired?"Route this decision to the accountable owner for review before acting.":"Continue monitoring the evidence for material changes.");
   }else{
    const error=[data.error,data.details].filter(Boolean).join(" ")||"OpenAI Decisions returned no assessment.";
    decision={status:"failed",profileName:data.profileUsed?.name||profile?.name||"Default decision profile",provider:"openai-decisions",model:"gpt-6-luna",error};
    modelNote="Luna could not complete the decision; review the error in the assessment output.";
   }
  }catch(error){
   const message=error instanceof Error?error.message:"Could not reach OpenAI Decisions.";
   decision={status:"failed",profileName:profile?.name||"Default decision profile",provider:"openai-decisions",model:"gpt-6-luna",error:message};
   modelNote="Luna could not complete the decision; review the error in the assessment output.";
  }
  if(!recommendation)recommendation=level==="High"||level==="Critical"?"Route to the accountable owner for human review, validate the evidence, and record the decision before acting.":"Validate the evidence, confirm business impact, and assign an accountable owner.";
  const source=assessment.source==="File upload"&&assessmentFileName?`Uploaded file · ${assessmentFileName}`:assessment.source;
  const r:Risk={...assessment,id:`RSK-${1043+risks.length-seedRisks.length}`,level,title:assessment.title.trim(),detail:assessment.detail.trim(),status:"Needs review",time:"Just now",owner:assessment.team==="Cross-team"?"Cross-functional owner":`${assessment.team} team`,evidence:assessment.evidence.trim()||"No evidence supplied yet. Evidence validation is required.",recommendation,source,decision};
  setRisks(old=>[r,...old]);setModal(null);setAssessmentFileName("");setAssessmentProfileId("");setAssessmentQuickProfile(null);setAssessment({title:"",team:"Engineering",detail:"",level:"Medium",source:"Manual assessment",evidence:"",recommendation:""});setSection("Risk assessments");notify(`Assessment saved. ${modelNote}`);
 }
 async function assessConnectorSource(source:any):Promise<Risk>{
  const profile=profiles.find(item=>item.active&&sourceNames(item).includes(String(source.name)));
  const team=profile?.team||(source.name==="GitHub"||source.name==="Jira"?"Engineering":"Cross-team");
  const sourceLabel=source.repository?`GitHub · ${source.repository}`:source.name;
  const title=source.repository?`${source.repository} risk assessment`:`${source.name} risk signal review`;
  const evidence=JSON.stringify((source.items||[]).slice(0,8),null,2);
  let level:Level="Medium";
  let recommendation=profile?"Review the decision output and validate the connector evidence.":"Map this data source to an active decision profile, then sync again.";
  let decision:DecisionOutput|null=null;
  if(profile){
   try{
    const response=await fetch("/api/decisions",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({state:{title,team,detail:source.signal||`${source.count} records received from ${source.name}.`,evidence,source:sourceLabel},profile:{id:profile.id,name:profile.name,predicate:profile.predicate,choices:profile.choices,scores:profile.scores,fields:profile.fields,approval:profile.approval}})});
    const data=await response.json();
    if(response.ok&&data.assessment){decision=decisionOutput(data,profile);level=data.assessment.severity as Level;recommendation=decision.recommendedActions?.[0]||recommendation;}
    else decision={status:"failed",profileName:profile.name,provider:"openai-decisions",model:"gpt-6-luna",error:[data.error,data.details].filter(Boolean).join(" ")||"OpenAI Decisions returned no assessment."};
   }catch(error){decision={status:"failed",profileName:profile.name,provider:"openai-decisions",model:"gpt-6-luna",error:error instanceof Error?error.message:"Could not reach OpenAI Decisions."};}
  }
  return {id:`RSK-${Date.now()}-${String(source.name).replace(/[^a-z0-9]+/gi,"-")}`,title,team,level,status:"Needs review",detail:source.signal||`${source.count} records received from ${source.name}.`,source:sourceLabel,time:"Just now",owner:team==="Cross-team"?"Cross-functional owner":`${team} team`,evidence,recommendation,decision};
 }
 async function syncConfiguredConnectors(){
  setSyncing(true);
  try{
   const res=await fetch("/api/connectors/sync",{method:"POST"});
   const data=await res.json();
   if(!res.ok)throw new Error(data.error||"Sync failed");
   const sourceResults=data.sources||[];
   const updates=sourceResults.map((source:any)=>`${source.name}: ${source.connected?source.count+" records fetched":"not configured"}`).join(" · ");
   const eligible=sourceResults.filter((source:any)=>source.connected&&source.count>0);
   const signals=await Promise.all(eligible.map((source:any)=>assessConnectorSource(source)));
   if(signals.length)setRisks(old=>[...signals,...old.filter(existing=>!signals.some(next=>next.title===existing.title&&next.source===existing.source))]);
   setConnectors(old=>old.map(connector=>{const source=sourceResults.find((item:any)=>item.name===connector.name);if(!source)return connector;return {...connector,status:source.connected?"Connected":"Not connected",lastSync:source.connected?`Synced just now · ${source.count} records`:source.setup||"Credentials required"};}));
   const analyzed=signals.filter(signal=>signal.decision?.status==="success").length;
   const unmapped=eligible.length-signals.filter(signal=>Boolean(signal.decision)).length;
   notify(`${updates||"No configured connectors"}${analyzed?`; ${analyzed} analyzed with Luna`:""}${unmapped?`; ${unmapped} need a profile mapping`:""}${data.errors?.length?"; errors: "+data.errors.join("; "):""}`);
  }catch(error){notify(error instanceof Error?error.message:"Connector sync failed");}
  finally{setSyncing(false);}
 }
 async function connectSource(name:string,config:ConnectorConfig):Promise<ConnectionResult>{
  setSyncing(true);
  try{
   const response=await fetch("/api/connectors/sync",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({connector:name,config})});
   const data=await response.json();
   if(!response.ok)return{ok:false,message:data.error||"Connection request failed."};
   const source=(data.sources||[]).find((item:any)=>item.name===name);
   if(!source?.connected)return{ok:false,message:source?.error||data.errors?.[0]||source?.setup||"Could not connect this source."};
   setConnectors(old=>old.map(connector=>connector.name===name?{...connector,status:"Connected",lastSync:`Synced just now · ${source.count} records`}:connector));
   let analyzed=false;
   if(source.count>0){const risk=await assessConnectorSource(source);analyzed=risk.decision?.status==="success";setRisks(old=>[risk,...old.filter(item=>!(item.title===risk.title&&item.source===risk.source))]);}
   const mapped=profiles.some(profile=>profile.active&&sourceNames(profile).includes(name));
   const message=`${name} connected successfully. ${source.count} record(s) fetched.${analyzed?" Evidence analyzed with Luna.":mapped?" Decision analysis failed; open the risk for details.":" Map this source in a decision profile to analyze it automatically."}`;
   notify(message);return{ok:true,message};
  }catch(error){return{ok:false,message:error instanceof Error?error.message:"Connection request failed."};}
  finally{setSyncing(false);}
 }
 function toggleProfileSource(name:string){setProfileDraft(profile=>{const selected=new Set(sourceNames(profile));if(selected.has(name))selected.delete(name);else selected.add(name);return{...profile,sources:[...selected].join(", ")};});}
 function saveProfile(){if(!profileDraft.name.trim()||!profileDraft.predicate.trim()){notify("Profile name and Predicate question are required.");return;}setProfiles(old=>old.some(p=>p.id===profileDraft.id)?old.map(p=>p.id===profileDraft.id?profileDraft:p):[...old,{...profileDraft,id:profileDraft.id||`profile-${Date.now()}`}]);setModal(null);notify("Decision profile saved.");}
 function addConnector(){if(!connectorDraft.name.trim()){notify("Enter a connector name.");return;}setConnectors(old=>[...old,{...connectorDraft,name:connectorDraft.name.trim(),status:"Not connected",lastSync:"Setup required"}]);setConnectorDraft({name:"",team:"Engineering",description:""});setModal(null);notify("Connector added to this workspace.");}
 function exportRisks(){const esc=(v:string)=>`"${String(v).replace(/"/g,'""')}"`;const csv=[["ID","Title","Team","Severity","Status","Description","Evidence","Recommendation","Owner"].join(","),...risks.map(r=>[r.id,r.title,r.team,r.level,r.status,r.detail,r.evidence,r.recommendation,r.owner].map(esc).join(","))].join("\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8;"}));a.download="sentinel-risk-register.csv";a.click();URL.revokeObjectURL(a.href);notify("Risk register exported as CSV.");}
 function markReviewed(r:Risk){setRisks(old=>old.map(x=>x.id===r.id?{...x,status:"Monitoring"}:x));setSelectedRisk(null);notify("Risk moved to Monitoring.");}
 if(!hydrated)return <main className="flex min-h-screen items-center justify-center bg-[#F5F7F5] text-sm text-slate-500">Loading your Sentinel workspace…</main>;
 return <div className="min-h-screen bg-[#F5F7F5] text-[#17211F]">
 {toast&&<div className="fixed right-4 top-4 z-[100] flex items-center gap-2 rounded-xl bg-[#17211F] px-4 py-3 text-sm text-white shadow-xl"><CheckCircle2 size={17} className="text-emerald-300"/>{toast}</div>}
 <div className="flex min-h-screen">
 {mobileNav&&<button className="fixed inset-0 z-30 bg-black/30 lg:hidden" onClick={()=>setMobileNav(false)} aria-label="Close menu"/>}
 <aside className={cls("fixed inset-y-0 left-0 z-40 flex w-[250px] flex-col border-r border-slate-200 bg-white transition-transform lg:static lg:translate-x-0",mobileNav?"translate-x-0":"-translate-x-full")}>
  <div className="flex h-[76px] items-center gap-3 border-b border-slate-100 px-5"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#176B57] text-white"><Shield size={22}/></span><div><p className="text-lg font-extrabold">sentinel<span className="text-emerald-700">.</span></p><p className="text-[10px] font-bold uppercase tracking-[.16em] text-slate-400">Risk intelligence</p></div><button className="ml-auto lg:hidden" onClick={()=>setMobileNav(false)}><X size={18}/></button></div>
  <div className="px-4 pt-6"><p className="mb-3 px-2 text-[10px] font-bold uppercase tracking-[.16em] text-slate-400">Workspace</p>{nav.map(n=>{const I=n.icon;return <button key={n.label} onClick={()=>{setSection(n.label);setMobileNav(false);setSearch("");}} className={cls("mb-1 flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-semibold",section===n.label?"bg-emerald-50 text-[#176B57]":"text-slate-600 hover:bg-slate-50")}><I size={18}/>{n.label}{n.label==="Risk assessments"&&<span className="ml-auto rounded-md bg-white px-1.5 py-0.5 text-[10px]">{risks.length}</span>}</button>})}</div>
  <div className="mt-auto p-4"><div className="rounded-xl bg-emerald-50 p-3"><p className="flex items-center gap-2 text-xs font-bold text-emerald-900"><Sparkles size={14}/>Early warning, not hindsight</p><p className="mt-2 text-xs leading-5 text-slate-600">Connect organizational signals to uncover emerging risk patterns.</p><button onClick={()=>setSection("Data connectors")} className="mt-2 text-xs font-bold text-emerald-800">Connect a source →</button></div><div className="mt-4 rounded-2xl border border-slate-200 bg-slate-50 p-3"><div className="flex items-center gap-2"><BriefcaseBusiness size={17} className="text-emerald-700"/><div><p className="text-sm font-bold">Sentinel workspace</p><p className="text-xs text-slate-500">Shared Neon workspace</p></div></div><div className="mt-4 flex justify-between border-t border-slate-200 pt-3 text-xs"><span className="text-slate-500">Connected sources</span><b>{connectors.filter(c=>c.status==="Connected").length}/{connectors.length}</b></div></div></div>
 </aside>
 <main className="min-w-0 flex-1">
  <header className="sticky top-0 z-20 flex h-[76px] items-center justify-between border-b border-slate-200 bg-white/90 px-4 backdrop-blur sm:px-7 xl:px-10"><div className="flex items-center gap-3"><button onClick={()=>setMobileNav(true)} className="lg:hidden"><Menu size={20}/></button><span className="hidden text-xs text-slate-400 sm:inline">Workspace</span><ChevronRight size={13} className="hidden text-slate-300 sm:inline"/><span className="text-sm font-bold">{section}</span></div><div className="flex items-center gap-2 sm:gap-3"><div className="relative hidden md:block"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search current view..." className="h-10 w-56 rounded-xl border border-slate-200 bg-slate-50 pl-9 pr-3 text-xs outline-none focus:border-emerald-700"/></div><button title="Notifications" onClick={()=>notify("No new notifications in this demo.")} className="flex h-10 w-10 items-center justify-center rounded-xl border border-slate-200 bg-white"><Bell size={17}/></button><Button onClick={()=>setModal("assessment")}><Plus size={16}/> <span className="hidden sm:inline">New assessment</span><span className="sm:hidden">New</span></Button></div></header>
  <div className="mx-auto max-w-[1450px] px-4 py-7 sm:px-7 sm:py-9 xl:px-10">
  {section==="Overview"&&<><Heading eyebrow="ORGANIZATION RISK INTELLIGENCE" title="Your risk pulse, at a glance." desc="Spot signals that could disrupt your goals, understand what connects them, and decide what needs attention." action={<Button secondary onClick={()=>setSection("Risk assessments")}><ClipboardCheck size={16}/>Review risks</Button>}/><div className="mb-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Open risks" value={String(risks.filter(r=>r.status!=="Resolved").length).padStart(2,"0")} note="Across all teams" icon={ShieldAlert}/><Metric label="Needs review" value={String(risks.filter(r=>r.status==="Needs review").length).padStart(2,"0")} note="Awaiting a decision" icon={AlertCircle}/><Metric label="Connected sources" value={`${connectors.filter(c=>c.status==="Connected").length}/${connectors.length}`} note="Connector catalog" icon={Link2}/><Metric label="Risk profiles" value={String(profiles.filter(p=>p.active).length).padStart(2,"0")} note="Active decision profiles" icon={SlidersHorizontal}/></div><div className="grid gap-6 xl:grid-cols-[1.2fr_1fr]"><section className="rounded-2xl border border-slate-200 bg-white p-5 sm:p-6"><div className="mb-5 flex items-center justify-between"><div><h2 className="font-bold">Team risk overview</h2><p className="mt-1 text-xs text-slate-500">Current sample risk signals by team</p></div><Pill>Demo data</Pill></div><div className="grid gap-3 sm:grid-cols-2">{teams.slice(0,4).map(t=>{const teamRisks=risks.filter(r=>r.team===t&&r.status!=="Resolved");const score=Math.min(95,teamRisks.reduce((a,r)=>a+(r.level==="Critical"?40:r.level==="High"?30:r.level==="Medium"?18:8),0));return <button key={t} onClick={()=>{setSection("Risk assessments");setSearch(t);}} className="rounded-xl border border-slate-200 p-4 text-left hover:border-emerald-300"><div className="flex items-center gap-3"><TeamIcon team={t}/><div className="flex-1"><p className="text-sm font-bold">{t}</p><p className="text-xs text-slate-500">{teamRisks.length} open risk(s)</p></div><ChevronRight size={16} className="text-slate-300"/></div><div className="mt-4 flex justify-between text-xs"><span className={score>50?"text-orange-700":"text-slate-500"}>{score>50?"Elevated risk":score>20?"Watch closely":"Healthy"}</span><b>{score}/100</b></div><div className="mt-2 h-1.5 rounded-full bg-slate-100"><div className={cls("h-1.5 rounded-full",score>50?"bg-orange-400":score>20?"bg-amber-400":"bg-emerald-500")} style={{width:`${score}%`}}/></div></button>})}</div><div className="mt-5 flex gap-3 rounded-xl bg-emerald-50 p-4"><Sparkles size={17} className="mt-0.5 shrink-0 text-emerald-800"/><p className="text-xs leading-5 text-slate-700"><b>Cross-team hypothesis:</b> Supplier delays and release blockers may affect the same launch milestone. Validate dependencies before escalating.</p></div></section><section className="overflow-hidden rounded-2xl border border-slate-200 bg-white"><div className="flex items-center justify-between border-b border-slate-100 p-5"><div><h2 className="font-bold">Priority watchlist</h2><p className="mt-1 text-xs text-slate-500">Start with these findings</p></div><Pill>{risks.filter(r=>r.level==="High"||r.level==="Critical").length} high</Pill></div><div className="divide-y divide-slate-100">{risks.filter(r=>r.status!=="Resolved").slice(0,4).map(r=><button key={r.id} onClick={()=>setSelectedRisk(r)} className="flex w-full gap-3 p-4 text-left hover:bg-slate-50"><span className={cls("mt-1 h-2 w-2 shrink-0 rounded-full",r.level==="Critical"||r.level==="High"?"bg-orange-500":r.level==="Medium"?"bg-amber-400":"bg-emerald-500")}/><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{r.title}</p><p className="mt-1 line-clamp-2 text-xs leading-5 text-slate-500">{r.detail}</p><p className="mt-2 text-[10px] text-slate-400">{r.team} · {r.time}</p></div><ChevronRight size={15} className="mt-1 text-slate-300"/></button>)}</div><button onClick={()=>setSection("Risk assessments")} className="flex w-full items-center justify-center gap-2 border-t border-slate-100 py-3 text-xs font-bold text-emerald-800 hover:bg-slate-50">View risk register <ArrowRight size={14}/></button></section></div><section className="mt-6 rounded-2xl border border-slate-200 bg-white p-5"><div className="mb-4"><h2 className="font-bold">Get started</h2><p className="mt-1 text-xs text-slate-500">Configure the core workflow, then connect real systems.</p></div><div className="grid gap-3 md:grid-cols-3"><StartCard icon={Link2} title="Connect data sources" desc="Manage team integrations and their demo connection status." onClick={()=>setSection("Data connectors")}/><StartCard icon={SlidersHorizontal} title="Configure decision profiles" desc="Define questions, allowed outputs, and approval rules." onClick={()=>setSection("Decision profiles")}/><StartCard icon={ShieldAlert} title="Run an assessment" desc="Capture a risk situation and expected evidence." onClick={()=>setModal("assessment")}/></div></section></>}
  {section==="Data connectors"&&<><Heading eyebrow="DATA FOUNDATION" title="Connect your organization." desc="Manage the sources that provide signals for risk detection." action={<div className="flex flex-wrap gap-2"><Button secondary disabled={syncing} onClick={syncConfiguredConnectors}><Activity size={16}/>{syncing?"Syncing…":"Sync configured sources"}</Button><Button onClick={()=>setModal("connector")}><Plus size={16}/>Add connector</Button></div>}/><div className="mb-5 flex flex-wrap gap-2">{["All teams",...teams].map(t=><button key={t} onClick={()=>setTeamFilter(t)} className={cls("rounded-lg px-3 py-2 text-xs font-semibold",teamFilter===t?"bg-[#176B57] text-white":"border border-slate-200 bg-white text-slate-600")}>{t}</button>)}</div><div className="grid items-start gap-4 md:grid-cols-2 xl:grid-cols-3">{shownConnectors.map(c=><ConnectorCard key={c.name} connector={c} onConnect={config=>connectSource(c.name,config)} onRemove={()=>{setConnectors(old=>old.filter(x=>x.name!==c.name));notify(`${c.name} removed from catalog.`)}}/>)}</div><p className="mt-5 rounded-xl border border-dashed border-emerald-200 bg-emerald-50 p-4 text-xs leading-5 text-slate-600"><LockKeyhole size={14} className="mr-2 inline text-emerald-800"/>GitHub and Jira can be connected directly from their cards. Credentials are used once; use server environment variables for persistent production sync. Setup instructions remain available on each connector card.</p></>}
  {section==="Decision profiles"&&<><Heading eyebrow="DECISION LOGIC" title="Define the expected output." desc="Configure each profile's questions, allowed values, output fields, and conditions that require human approval." action={<Button onClick={()=>{setProfileDraft({id:`profile-${Date.now()}`,name:"",team:"Engineering",description:"",active:true,predicate:"",choices:"",scores:"Low, Medium, High, Critical",fields:"risk_detected, severity, evidence, recommendation, confidence, human_approval_required",approval:"High or Critical severity; low confidence; missing evidence",sources:""});setModal("profile")}}><Plus size={16}/>New profile</Button>}/><div className="space-y-4">{profiles.map(p=><div key={p.id} className="rounded-2xl border border-slate-200 bg-white p-5 sm:p-6"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div className="flex gap-3"><span className="flex h-11 w-11 items-center justify-center rounded-xl bg-emerald-50 text-emerald-800"><ListChecks size={20}/></span><div><div className="flex flex-wrap items-center gap-2"><h3 className="font-bold">{p.name}</h3><Pill>{p.active?"Active":"Draft"}</Pill></div><p className="mt-1 text-xs leading-5 text-slate-500">{p.description||"No description added."}</p><p className="mt-2 text-[11px] text-slate-400">{p.team} · Predicate, Choice, Score</p></div></div><div className="flex gap-2"><Button secondary onClick={()=>{setProfileDraft({...p});setModal("profile")}}>Edit configuration</Button><button title="Delete profile" onClick={()=>{setProfiles(old=>old.filter(x=>x.id!==p.id));notify("Profile deleted.")}} className="rounded-xl border border-slate-200 px-3 text-slate-500 hover:bg-red-50 hover:text-red-600"><Trash2 size={16}/></button></div></div><div className="mt-5 grid gap-3 md:grid-cols-3"><ProfileField label="PREDICATE · YES/NO" value={p.predicate}/><ProfileField label="CHOICE · ALLOWED OPTIONS" value={p.choices}/><ProfileField label="SCORE · ORDERED SEVERITY" value={p.scores}/></div><div className="mt-3 rounded-xl bg-slate-50 p-3"><p className="text-[10px] font-bold uppercase tracking-wider text-slate-400">Mapped data sources</p><p className="mt-1 text-xs leading-5 text-slate-600">{sourceNames(p).join(", ")||"No sources mapped. Connector evidence will not run automatically."}</p><p className="mt-3 text-[10px] font-bold uppercase tracking-wider text-slate-400">Required output fields</p><p className="mt-1 break-words text-xs leading-5 text-slate-600">{p.fields}</p><p className="mt-3 text-[10px] font-bold uppercase tracking-wider text-slate-400">Human approval rule</p><p className="mt-1 text-xs leading-5 text-slate-600">{p.approval}</p></div></div>)}</div></>}
  {section==="Risk assessments"&&<><Heading eyebrow="RISK REGISTER" title="Risk assessments" desc="Inspect findings, evidence, and next actions. Review decisions are saved to the shared Neon workspace." action={<Button secondary onClick={exportRisks}><FileDown size={16}/>Export CSV</Button>}/><div className="mb-4 grid gap-3 sm:grid-cols-3"><Metric label="Total risks" value={String(risks.length)} note="Saved workspace records" icon={ShieldAlert}/><Metric label="Needs review" value={String(risks.filter(r=>r.status==="Needs review").length)} note="Requires attention" icon={AlertCircle}/><Metric label="Monitoring" value={String(risks.filter(r=>r.status==="Monitoring").length)} note="Being tracked" icon={Activity}/></div><div className="overflow-hidden rounded-2xl border border-slate-200 bg-white"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 p-4"><div><h2 className="text-sm font-bold">All detected risks</h2><p className="mt-1 text-xs text-slate-500">Select a row to inspect evidence and recommendations.</p></div><div className="flex flex-wrap gap-2"><select value={riskLevel} onChange={e=>setRiskLevel(e.target.value)} className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs"><option>All levels</option>{levels.map(l=><option key={l}>{l}</option>)}</select><select value={riskStatus} onChange={e=>setRiskStatus(e.target.value)} className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs"><option>All statuses</option><option>Needs review</option><option>Monitoring</option><option>Resolved</option></select></div></div><div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left"><thead className="bg-slate-50 text-[10px] uppercase tracking-wider text-slate-400"><tr><th className="px-5 py-3">Risk</th><th className="px-4 py-3">Team</th><th className="px-4 py-3">Severity</th><th className="px-4 py-3">Status</th><th className="px-4 py-3">Detected</th><th/></tr></thead><tbody className="divide-y divide-slate-100">{shownRisks.map(r=><tr key={r.id} onClick={()=>setSelectedRisk(r)} className="cursor-pointer hover:bg-slate-50"><td className="px-5 py-4"><p className="text-sm font-semibold">{r.title}</p><p className="mt-1 text-[10px] text-slate-400">{r.id} · {r.source}</p></td><td className="px-4 py-4 text-xs">{r.team}</td><td className="px-4 py-4"><span className={cls("rounded-full px-2.5 py-1 text-xs font-semibold",severity(r.level))}>{r.level}</span></td><td className="px-4 py-4 text-xs">{r.status}</td><td className="px-4 py-4 text-xs text-slate-500">{r.time}</td><td className="px-4 py-4"><ChevronRight size={16} className="text-slate-300"/></td></tr>)}</tbody></table>{shownRisks.length===0&&<p className="p-10 text-center text-sm text-slate-500">No matching risks. Change your search or filters.</p>}</div><div className="border-t border-slate-100 px-5 py-3 text-[11px] text-slate-400">Showing {shownRisks.length} of {risks.length} risks · Shared Neon workspace storage</div></div></>}
  {section==="Data connectors"&&<QuickTestDataSource profiles={profiles} onUse={useTestData}/>}
  <footer className="mt-10 flex flex-col justify-between gap-2 border-t border-slate-200 py-5 text-[11px] text-slate-400 sm:flex-row"><p>© 2026 Sentinel Intelligence · Organization risk, made visible.</p><span className="flex items-center gap-1.5"><span className="h-1.5 w-1.5 rounded-full bg-emerald-500"/>Shared workspace · Neon PostgreSQL</span></footer>
  </div></main></div>

 {modal&&<div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/40 p-4 backdrop-blur-sm" onClick={()=>setModal(null)}><div className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-3xl bg-white p-6 shadow-2xl sm:p-8" onClick={e=>e.stopPropagation()}><div className="mb-6 flex items-start justify-between"><div><span className="mb-3 flex h-10 w-10 items-center justify-center rounded-xl bg-emerald-50 text-emerald-800">{modal==="assessment"?<ShieldAlert size={20}/>:modal==="profile"?<SlidersHorizontal size={20}/>:<Link2 size={20}/>}</span><h2 className="text-xl font-bold">{modal==="assessment"?"New risk assessment":modal==="profile"?"Configure decision profile":"Add data connector"}</h2><p className="mt-1 text-sm leading-5 text-slate-500">{modal==="assessment"?"Describe the risk and define what evidence and action should be captured.":modal==="profile"?"Specify the expected decision output for this risk type.":"Add a source to your connector catalog."}</p></div><button onClick={()=>setModal(null)} className="rounded-lg p-2 text-slate-400 hover:bg-slate-100"><X size={18}/></button></div>
 {modal==="assessment"&&<div className="space-y-4"><Field label="Assessment title *" value={assessment.title} onChange={v=>setAssessment(a=>({...a,title:v}))} placeholder="e.g. Product release readiness risk"/><div className="grid gap-4 sm:grid-cols-2"><label className="block"><span className="mb-1.5 block text-xs font-bold text-slate-600">Primary team</span><select value={assessment.team} onChange={e=>setAssessment(a=>({...a,team:e.target.value}))} className="w-full rounded-xl border border-slate-200 px-3 py-2.5 text-sm">{teams.map(t=><option key={t}>{t}</option>)}</select></label><label className="block"><span className="mb-1.5 block text-xs font-bold text-slate-600">Decision profile</span><select value={assessmentProfileId} onChange={event=>chooseAssessmentProfile(event.target.value)} className="w-full rounded-xl border border-slate-200 px-3 py-2.5 text-sm"><option value="">{assessmentQuickProfile?"Quick test profile":"Automatic mapped/team profile"}</option>{profiles.map(profile=><option key={profile.id} value={profile.id}>{profile.name} · {profile.team}</option>)}</select></label></div><label className="block"><span className="mb-1.5 block text-xs font-bold text-slate-600">Situation to assess *</span><textarea rows={3} value={assessment.detail} onChange={e=>setAssessment(a=>({...a,detail:e.target.value}))} placeholder="Describe the situation, constraints, and possible impact…" className="w-full rounded-xl border border-slate-200 px-3 py-2.5 text-sm outline-none focus:border-emerald-700"/></label><label className="block"><span className="mb-1.5 block text-xs font-bold text-slate-600">Data source</span><select value={assessment.source} onChange={event=>chooseAssessmentSource(event.target.value)} className="w-full rounded-xl border border-slate-200 px-3 py-2.5 text-sm"><option value="Manual assessment">Manual / pasted evidence</option><option value="File upload">File upload</option>{connectors.map(connector=><option key={connector.name} value={connector.name}>{connector.name} · {connector.status}</option>)}</select></label>{assessment.source==="File upload"&&<label className="flex cursor-pointer items-center gap-3 rounded-xl border border-dashed border-emerald-300 bg-emerald-50 p-4 text-emerald-900"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-white"><Upload size={18}/></span><span className="min-w-0 flex-1"><span className="block text-sm font-bold">{assessmentFileName||"Choose a text file"}</span><span className="mt-0.5 block text-xs text-emerald-800/70">TXT, Markdown, CSV, or JSON · 100 KB maximum</span></span><input type="file" accept=".txt,.md,.csv,.json,text/plain,text/csv,application/json" className="sr-only" onChange={event=>uploadAssessmentFile(event.target.files?.[0])}/></label>}<label className="block"><span className="mb-1.5 block text-xs font-bold text-slate-600">Supporting evidence (optional)</span><span className="mb-2 block text-xs leading-5 text-slate-500">Add the facts Luna should evaluate: issue details, metrics, dates, links, or synced connector records.</span><textarea rows={4} value={assessment.evidence} onChange={e=>setAssessment(a=>({...a,evidence:e.target.value}))} placeholder="Example: 3 pull requests are blocked, the release is in 7 days, and two critical bugs remain open." className="w-full rounded-xl border border-slate-200 px-3 py-2.5 text-sm"/></label><div className="flex justify-end gap-2"><Button secondary onClick={()=>setModal(null)}>Cancel</Button><Button onClick={createAssessment}><Save size={15}/>Save assessment</Button></div></div>}
 {modal==="connector"&&<div className="space-y-4"><Field label="Connector name *" value={connectorDraft.name} onChange={v=>setConnectorDraft(c=>({...c,name:v}))} placeholder="e.g. Salesforce / Internal ERP"/><label className="block"><span className="mb-1.5 block text-xs font-bold text-slate-600">Team</span><select value={connectorDraft.team} onChange={e=>setConnectorDraft(c=>({...c,team:e.target.value}))} className="w-full rounded-xl border border-slate-200 px-3 py-2.5 text-sm">{teams.map(t=><option key={t}>{t}</option>)}</select></label><label className="block"><span className="mb-1.5 block text-xs font-bold text-slate-600">Description</span><textarea value={connectorDraft.description} onChange={e=>setConnectorDraft(c=>({...c,description:e.target.value}))} rows={3} placeholder="What data signals does this source provide?" className="w-full rounded-xl border border-slate-200 px-3 py-2.5 text-sm"/></label><p className="text-xs text-slate-500">This adds a workspace catalog entry. Credentials are configured server-side in .env.local or Vercel; see CONNECTORS.md.</p><div className="flex justify-end gap-2"><Button secondary onClick={()=>setModal(null)}>Cancel</Button><Button onClick={addConnector}><Plus size={15}/>Add connector</Button></div></div>}
 {modal==="profile"&&<div className="space-y-4"><Field label="Profile name *" value={profileDraft.name} onChange={v=>setProfileDraft(p=>({...p,name:v}))} placeholder="e.g. Release readiness"/><label className="block"><span className="mb-1.5 block text-xs font-bold text-slate-600">Team</span><select value={profileDraft.team} onChange={e=>setProfileDraft(p=>({...p,team:e.target.value}))} className="w-full rounded-xl border border-slate-200 px-3 py-2.5 text-sm">{teams.map(t=><option key={t}>{t}</option>)}</select></label><div className="rounded-xl border border-slate-200 bg-slate-50 p-4"><p className="text-xs font-bold text-slate-700">Connected data sources</p><p className="mt-1 text-[11px] leading-5 text-slate-500">Mapped sources will use this profile automatically after they connect and sync.</p><div className="mt-3 grid gap-2 sm:grid-cols-2">{connectors.map(connector=><label key={connector.name} className="flex min-h-10 cursor-pointer items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2"><input type="checkbox" checked={sourceNames(profileDraft).includes(connector.name)} onChange={()=>toggleProfileSource(connector.name)} className="accent-emerald-700"/><span className="min-w-0 flex-1 text-xs font-semibold text-slate-700">{connector.name}</span><Pill>{connector.status}</Pill></label>)}</div></div><Field label="Description" value={profileDraft.description} onChange={v=>setProfileDraft(p=>({...p,description:v}))} placeholder="What should this profile assess?"/><Field label="Predicate question (yes/no) *" value={profileDraft.predicate} onChange={v=>setProfileDraft(p=>({...p,predicate:v}))} placeholder="Is this situation a material risk?"/><Field label="Choice options (comma-separated)" value={profileDraft.choices} onChange={v=>setProfileDraft(p=>({...p,choices:v}))} placeholder="Delay, Quality, Resource dependency, None"/><Field label="Ordered Score levels (comma-separated)" value={profileDraft.scores} onChange={v=>setProfileDraft(p=>({...p,scores:v}))} placeholder="Low, Medium, High, Critical"/><label className="block"><span className="mb-1.5 block text-xs font-bold text-slate-600">Required output fields (comma-separated)</span><textarea rows={2} value={profileDraft.fields} onChange={e=>setProfileDraft(p=>({...p,fields:e.target.value}))} className="w-full rounded-xl border border-slate-200 px-3 py-2.5 text-sm"/></label><label className="block"><span className="mb-1.5 block text-xs font-bold text-slate-600">Human approval rules</span><textarea rows={2} value={profileDraft.approval} onChange={e=>setProfileDraft(p=>({...p,approval:e.target.value}))} className="w-full rounded-xl border border-slate-200 px-3 py-2.5 text-sm"/></label><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={profileDraft.active} onChange={e=>setProfileDraft(p=>({...p,active:e.target.checked}))} className="accent-emerald-700"/>Profile is active</label><div className="rounded-xl bg-amber-50 p-3 text-xs leading-5 text-amber-900">These settings are stored in your Neon workspace. GPT-6 Luna uses the Predicate question, Choice options, and ordered Score levels for subsequent OpenAI Decisions assessments.</div><div className="flex justify-end gap-2"><Button secondary onClick={()=>setModal(null)}>Cancel</Button><Button onClick={saveProfile}><Save size={15}/>Save profile</Button></div></div>}
 </div></div>}

 {selectedRisk&&<div className="fixed inset-0 z-[60] flex justify-end bg-slate-950/30" onClick={()=>setSelectedRisk(null)}><aside className="h-full w-full max-w-xl overflow-y-auto bg-white shadow-2xl" onClick={e=>e.stopPropagation()}><div className="sticky top-0 flex items-center justify-between border-b border-slate-100 bg-white p-5"><div><p className="text-[10px] font-bold uppercase tracking-wider text-slate-400">{selectedRisk.id} · Risk detail</p><p className="mt-1 font-bold">Assessment details</p></div><button onClick={()=>setSelectedRisk(null)}><X size={18}/></button></div><div className="p-6 sm:p-8"><span className={cls("rounded-full px-3 py-1 text-xs font-bold",severity(selectedRisk.level))}>{selectedRisk.level} severity</span><h2 className="mt-4 text-2xl font-bold">{selectedRisk.title}</h2><p className="mt-3 text-sm leading-6 text-slate-600">{selectedRisk.detail}</p><div className="mt-6 grid grid-cols-2 gap-3"><Info label="Team" value={selectedRisk.team}/><Info label="Status" value={selectedRisk.status}/><Info label="Owner" value={selectedRisk.owner}/><Info label="Source" value={selectedRisk.source}/></div><DecisionOutputPanel decision={selectedRisk.decision}/><div className="mt-7"><h3 className="flex items-center gap-2 text-sm font-bold"><Database size={16} className="text-emerald-800"/>Evidence</h3><EvidenceDisplay evidence={selectedRisk.evidence} fallback={selectedRisk.detail}/></div><div className="mt-6"><h3 className="flex items-center gap-2 text-sm font-bold"><Sparkles size={16} className="text-emerald-800"/>Recommended next step</h3><p className="mt-2 rounded-xl bg-emerald-50 p-4 text-sm leading-6 text-slate-700">{selectedRisk.recommendation}</p></div><div className="mt-8 flex flex-wrap gap-2"><Button onClick={()=>markReviewed(selectedRisk)}><Check size={16}/>Mark as monitoring</Button><Button secondary onClick={()=>{setRisks(old=>old.map(r=>r.id===selectedRisk.id?{...r,status:"Resolved"}:r));setSelectedRisk(null);notify("Risk marked resolved.");}}>Mark resolved</Button><Button secondary onClick={()=>{navigator.clipboard?.writeText(`${selectedRisk.title}\nSeverity: ${selectedRisk.level}\nEvidence: ${selectedRisk.evidence}\nRecommendation: ${selectedRisk.recommendation}`);notify("Risk summary copied if clipboard permission is available.");}}>Copy summary</Button></div><p className="mt-5 text-[11px] leading-5 text-slate-400">Risk evidence and model outputs should be reviewed by an accountable owner. OpenAI Decisions outputs are advisory; deterministic approval rules apply before action.</p></div></aside></div>}
 </div>;
}
function Heading({eyebrow,title,desc,action}:{eyebrow:string;title:string;desc:string;action?:React.ReactNode}){return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="mb-2 text-[10px] font-bold uppercase tracking-[.16em] text-emerald-800">{eyebrow}</p><h1 className="text-2xl font-extrabold tracking-tight sm:text-[30px]">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-500">{desc}</p></div>{action}</div>}
function Metric({label,value,note,icon:Icon}:{label:string;value:string;note:string;icon:any}){return <div className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-start justify-between"><p className="text-xs font-semibold text-slate-500">{label}</p><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-emerald-50 text-emerald-800"><Icon size={18}/></span></div><p className="mt-4 text-3xl font-extrabold">{value}</p><p className="mt-2 text-xs text-slate-400">{note}</p></div>}
function ProfileField({label,value}:{label:string;value:string}){return <div className="rounded-xl border border-slate-100 p-3"><p className="text-[9px] font-bold tracking-wider text-slate-400">{label}</p><p className="mt-2 text-xs leading-5 text-slate-600">{value||"Not configured"}</p></div>}
function Info({label,value}:{label:string;value:string}){return <div className="rounded-xl border border-slate-200 p-3"><p className="text-[10px] text-slate-400">{label}</p><p className="mt-1 text-sm font-semibold">{value}</p></div>}
function evidenceLabel(value:string){return value.replace(/([a-z0-9])([A-Z])/g,"$1 $2").replace(/[_-]+/g," ").replace(/\b\w/g,letter=>letter.toUpperCase());}
function EvidenceValue({value}:{value:any}){
 if(value===null||value===undefined||value==="")return <span className="text-slate-400">Not provided</span>;
 if(typeof value==="boolean")return <span>{value?"Yes":"No"}</span>;
 if(typeof value==="string"&&/^https?:\/\//i.test(value))return <a href={value} target="_blank" rel="noreferrer" className="break-all font-semibold text-emerald-800 underline decoration-emerald-200 underline-offset-2">Open source link</a>;
 if(Array.isArray(value))return <div className="space-y-2">{value.map((item,index)=>typeof item==="object"&&item!==null?<div key={index} className="rounded-xl border border-slate-200 bg-white p-3"><EvidenceObject value={item}/></div>:<div key={index} className="flex gap-2 text-sm leading-5 text-slate-700"><CheckCircle2 size={14} className="mt-0.5 shrink-0 text-emerald-700"/><span>{String(item)}</span></div>)}</div>;
 if(typeof value==="object")return <div className="rounded-xl bg-slate-50 p-3"><EvidenceObject value={value}/></div>;
 return <span>{String(value)}</span>;
}
function EvidenceObject({value}:{value:Record<string,any>}){return <dl className="grid gap-3 sm:grid-cols-2">{Object.entries(value).map(([key,item])=>{const complex=typeof item==="object"&&item!==null;return <div key={key} className={complex?"sm:col-span-2":""}><dt className="text-[10px] font-bold uppercase tracking-wider text-slate-400">{evidenceLabel(key)}</dt><dd className="mt-1 break-words text-sm leading-5 text-slate-700"><EvidenceValue value={item}/></dd></div>;})}</dl>}
function EvidenceDisplay({evidence,fallback}:{evidence?:string;fallback:string}){
 const raw=(evidence||fallback).trim();
 let heading="";let candidate=raw;
 const separator=raw.indexOf("\n\n");
 if(separator>0&&raw.slice(0,separator).toLowerCase().startsWith("uploaded file:")){heading=raw.slice(0,separator);candidate=raw.slice(separator+2).trim();}
 try{const parsed=JSON.parse(candidate);return <div className="mt-2 space-y-3">{heading&&<p className="rounded-xl bg-slate-50 px-3 py-2 text-xs font-semibold text-slate-600">{heading}</p>}{Array.isArray(parsed)?<div className="space-y-3">{parsed.length?parsed.map((item,index)=><article key={index} className="rounded-xl border border-slate-200 bg-white p-4"><p className="mb-3 text-xs font-bold text-slate-500">Evidence item {index+1}</p>{typeof item==="object"&&item!==null?<EvidenceObject value={item}/>:<EvidenceValue value={item}/>}</article>):<p className="rounded-xl bg-slate-50 p-4 text-sm text-slate-500">No evidence items were returned by this source.</p>}</div>:typeof parsed==="object"&&parsed!==null?<div className="rounded-xl border border-slate-200 bg-white p-4"><EvidenceObject value={parsed}/></div>:<EvidenceValue value={parsed}/>}</div>;}catch{return <p className="mt-2 whitespace-pre-wrap rounded-xl border border-slate-200 bg-white p-4 text-sm leading-6 text-slate-600">{raw}</p>}
}
function decisionExplanation(decision:DecisionOutput){return [{label:"Risk likelihood",value:typeof decision.riskProbability==="number"?`${Math.round(decision.riskProbability*100)}% probability of material risk`:"Probability was not returned"},{label:"Classification",value:decision.riskType||"No category was returned"},{label:"Severity",value:decision.severity||"No severity was returned"},{label:"Review requirement",value:decision.humanApprovalRequired?"Human review is required before action":"Eligible for the configured automated policy"}];}
function DecisionOutputPanel({decision}:{decision?:DecisionOutput|null}){
 if(!decision)return <section className="mt-7 rounded-2xl border border-amber-200 bg-amber-50 p-4"><div className="flex items-start gap-3"><CircleHelp size={18} className="mt-0.5 shrink-0 text-amber-700"/><div><h3 className="text-sm font-bold text-amber-950">No structured decision output</h3><p className="mt-1 text-xs leading-5 text-amber-900/80">This assessment predates output tracking. Create a new assessment to run its Predicate, Choice, and Score profile with Luna.</p></div></div></section>;
 if(decision.status==="failed")return <section className="mt-7 rounded-2xl border border-red-200 bg-red-50 p-4"><div className="flex items-start gap-3"><AlertCircle size={18} className="mt-0.5 shrink-0 text-red-700"/><div className="min-w-0"><h3 className="text-sm font-bold text-red-950">Decision unavailable</h3><p className="mt-1 text-xs leading-5 text-red-900/80">Luna could not complete this profile. The assessment was saved with its manual severity.</p><dl className="mt-3 grid gap-2 text-xs sm:grid-cols-2"><div><dt className="font-semibold text-red-700">Profile</dt><dd className="mt-0.5 text-red-950">{decision.profileName||"Default decision profile"}</dd></div><div><dt className="font-semibold text-red-700">Model</dt><dd className="mt-0.5 text-red-950">{decision.model||"gpt-6-luna"}</dd></div></dl><p className="mt-3 break-words rounded-xl bg-white/70 p-3 text-xs leading-5 text-red-900">{decision.error||"OpenAI Decisions returned no result."}</p></div></div></section>;
 const percent=(value?:number)=>typeof value==="number"?`${Math.round(value*100)}%`:"—";
 const reviewRequired=Boolean(decision.humanApprovalRequired);
 return <section className="mt-7 overflow-hidden rounded-2xl border border-emerald-200 bg-white"><div className="flex flex-col gap-3 bg-emerald-50 p-4 sm:flex-row sm:items-start sm:justify-between"><div className="flex items-start gap-3"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-white text-emerald-800 shadow-sm"><Sparkles size={17}/></span><div><p className="text-[10px] font-bold uppercase tracking-[.14em] text-emerald-700">OpenAI Decisions output</p><h3 className="mt-1 text-base font-bold text-emerald-950">{decision.riskDetected?"Material risk detected":"No material risk detected"}</h3><p className="mt-1 text-[11px] text-emerald-800">{decision.profileName||"Default decision profile"} · {decision.model||"gpt-6-luna"}</p></div></div><span className={cls("w-fit rounded-full px-2.5 py-1 text-[11px] font-bold",reviewRequired?"bg-amber-100 text-amber-900":"bg-emerald-100 text-emerald-800")}>{reviewRequired?"Human review required":"Policy eligible"}</span></div><div className="p-4"><div className="grid gap-3 sm:grid-cols-3"><Info label="PREDICATE · RISK" value={`${decision.riskDetected?"Yes":"No"} · ${percent(decision.riskProbability)}`}/><Info label="CHOICE · RISK TYPE" value={decision.riskType||"Not returned"}/><Info label="SCORE · SEVERITY" value={`${decision.severity||"Not returned"} · ${percent(decision.confidence)} confidence`}/></div><div className="mt-4 rounded-xl bg-slate-50 p-4"><p className="text-[10px] font-bold uppercase tracking-[.12em] text-slate-400">Decision explanation</p><ul className="mt-3 space-y-2">{decisionExplanation(decision).map(item=><li key={item.label} className="flex items-start gap-2 text-sm leading-5 text-slate-700"><span className="mt-2 h-1.5 w-1.5 shrink-0 rounded-full bg-emerald-600"/><span><strong className="font-semibold text-slate-900">{item.label}:</strong> {item.value}</span></li>)}</ul></div>{decision.recommendedActions&&decision.recommendedActions.length>0&&<div className="mt-4 border-t border-slate-100 pt-4"><p className="text-[10px] font-bold uppercase tracking-[.12em] text-slate-400">Recommended actions</p><ul className="mt-2 space-y-2">{decision.recommendedActions.map((action,index)=><li key={`${action}-${index}`} className="flex gap-2 text-sm leading-5 text-slate-700"><CheckCircle2 size={15} className="mt-0.5 shrink-0 text-emerald-700"/><span>{action}</span></li>)}</ul></div>}<div className="mt-4 flex flex-wrap gap-x-5 gap-y-1 border-t border-slate-100 pt-3 text-[10px] text-slate-400"><span>Policy: {decision.policy||"Not returned"}</span><span>Provider: {decision.provider||"openai-decisions"}</span></div></div></section>;
}
function StartCard({icon:Icon,title,desc,onClick}:{icon:any;title:string;desc:string;onClick:()=>void}){return <button onClick={onClick} className="rounded-xl border border-slate-200 p-4 text-left transition hover:border-emerald-300 hover:bg-emerald-50/30"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-emerald-50 text-emerald-800"><Icon size={18}/></span><p className="mt-3 text-sm font-bold">{title}</p><p className="mt-1 text-xs leading-5 text-slate-500">{desc}</p><p className="mt-3 flex items-center gap-1 text-xs font-bold text-emerald-800">Open <ArrowRight size={13}/></p></button>}
